WITH RankedPosts AS (SELECT p.Id AS PostId, p.Title, p.CreationDate, p.Score, p.ViewCount, ROW_NUMBER() OVER (PARTITION BY p.PostTypeId ORDER BY p.CreationDate DESC NULLS FIRST) AS rn FROM Posts AS p WHERE p.CreationDate >= CAST('2024-10-01 12:34:56' AS Nullable(DateTime)) - INTERVAL '1' YEAR), UserStats AS (SELECT u.Id AS UserId, u.DisplayName, SUM(CASE WHEN v.VoteTypeId = 2 THEN 1 ELSE 0 END) AS UpVotes, SUM(CASE WHEN v.VoteTypeId = 3 THEN 1 ELSE 0 END) AS DownVotes, COUNT(b.Id) AS BadgeCount FROM Users AS u LEFT JOIN Votes AS v ON u.Id = v.UserId LEFT JOIN Badges AS b ON u.Id = b.UserId GROUP BY u.Id, u.DisplayName), PostCloseReasons AS (SELECT ph.PostId, GROUP_CONCAT(cr.Name, ', ') AS CloseReasons FROM PostHistory AS ph INNER JOIN CloseReasonTypes AS cr ON CAST(ph.Comment AS Nullable(Int32)) = cr.Id WHERE ph.PostHistoryTypeId = 10 GROUP BY ph.PostId) SELECT p.Title, p.CreationDate, u.DisplayName AS Owner, ps.UpVotes, ps.DownVotes, COALESCE(q.CloseReasons, 'Open') AS CloseReason, ranked.Score, ranked.ViewCount FROM RankedPosts AS ranked LEFT JOIN Posts AS p ON ranked.PostId = p.Id LEFT JOIN Users AS u ON p.OwnerUserId = u.Id LEFT JOIN UserStats AS ps ON u.Id = ps.UserId LEFT JOIN PostCloseReasons AS q ON p.Id = q.PostId WHERE ranked.rn = 1 ORDER BY ranked.CreationDate DESC NULLS FIRST LIMIT 100